import pathlib,json,urllib.request,concurrent.futures
r=pathlib.Path('.')
def put(p,s):
 p=r/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf-8')
articles=[
('choose-skin-specialist-mirpur','How to Choose a Skin Specialist in Mirpur, AJK','CONSULTATION','skin','A useful consultation starts with the right questions, not a treatment name.',[
('Start with your concern','Write down what has changed, how long it has been happening and what you have already tried. Acne, uneven tone, itching and hair shedding may need different types of assessment. Bring your medicines and skincare products, or photographs of their labels. This gives the consultation a clearer starting point than requesting a procedure first.'),
('Check the person behind the appointment','Ask for the practitioner’s full name, current professional registration and relevant training. Confirm these through the appropriate professional register where available. A title on social media alone does not establish specialist training. Ask who will assess you, who will perform any procedure and who will provide follow-up.'),
('Look for a reasoned recommendation','A helpful consultation connects the recommendation to your concern, health history and skin. Ask what other options exist, including waiting or using a simpler approach. If a practitioner cannot explain why a procedure is suitable, take time to seek clarification before consenting.'),
('Ask about practical safety','Ask how instruments are handled, what product or device will be used and what happens if a reaction occurs. Discuss your medicines, pregnancy or breastfeeding, allergies, skin infections and previous problems with healing. These details can change the treatment plan.'),
('Make room for the realities of Mirpur life','Tell your practitioner about travel, outdoor work, sun exposure and any upcoming event. Recovery instructions need to fit your daily routine. Confirm the exact location and opening hours before travelling, and ask how you can contact the clinic after a procedure.'),
('Leave with clarity, not pressure','Before deciding, understand the total cost, anticipated recovery, possible complications and review arrangements. There should be time to ask questions and consider your options. At Revive, begin by contacting the clinic; practitioner profile details remain subject to verification.')],['hydrafacial','acne-scar-consultation'], [('American Academy of Dermatology: acne scar consultation','https://www.aad.org/public/diseases/acne/derm-treat/scars/treatment/')]),
('hydrafacial-mirpur','HydraFacial in Mirpur: What to Know Before Booking','SKIN NOTES','portrait','Understand the facial, its limits and the questions to bring to your appointment.',[
('What the name describes','HydraFacial is a branded device-based facial that combines cleansing, exfoliation, extraction and hydration steps. Exact products, attachments and additions can differ. Ask the clinic which device and protocol it uses rather than assuming that every treatment advertised under a similar name is identical.'),
('A facial is not a diagnosis','You may be researching a facial because skin feels congested, dry or looks dull. Persistent acne, redness or pigmentation needs assessment in its own right. A cosmetic facial does not replace a diagnosis or an ongoing treatment plan for a skin condition.'),
('Discuss your current skin first','Tell the practitioner about sensitivity, active irritation, recent procedures and products such as exfoliating acids or retinoids. Share medicines, allergies and pregnancy or breastfeeding. Product ingredients and the intensity of exfoliation matter; ask whether treatment should be adapted or postponed.'),
('What to ask on the day','Ask what will be applied, how it may feel, which steps are optional and what the full price includes. You should understand the possibility of irritation and the aftercare before treatment starts. If a step feels painful or uncomfortable, say so rather than assuming discomfort is necessary.'),
('Keep expectations proportionate','A smoother or more hydrated feel is not the same as correcting deep scarring or treating an underlying disease. The extent and duration of visible changes vary. Avoid committing to a package based on a promised transformation or a fixed schedule before your skin has been assessed.'),
('Plan around your life','If you are preparing for a wedding or event in Mirpur, discuss timing well in advance. Trying a new procedure just before an important day leaves less room to manage unexpected irritation. Ask for a simple aftercare plan and when to resume your usual products.')],['hydrafacial','bridal-skincare-planning'], [('HydraFacial: treatment information','https://www.hydrafacial.com/')]),
('acne-scars-pigmentation','Acne Scars and Pigmentation: Understanding Treatment Options','SKIN NOTES','skin','Different marks need different conversations. Understanding the distinction is a useful first step.',[
('A mark is not always a scar','Flat areas of darker colour after acne and changes in skin texture are different concerns. They can occur together, but they do not necessarily respond to the same approach. An assessment should distinguish active acne, pigment changes and indented or raised scars before proposing a plan.'),
('Control the source of new marks','If acne is ongoing, ask how it will be managed alongside any corrective treatment. Addressing old marks while new inflamed lesions continue may be frustrating. Picking can worsen injury; seek a practical acne plan rather than repeatedly trying aggressive cosmetic products.'),
('Why there is no single scar treatment','Scar shape, depth, skin tone and healing history influence the options. A practitioner may discuss procedures such as microneedling, peels or other techniques. Some concerns require a combination or referral. A procedure that helps one type of scar may be a poor choice for another.'),
('Peels and microneedling need individual assessment','These procedures create controlled changes in the skin and require appropriate technique and aftercare. Ask about the depth, products or device, expected recovery and the chance of pigment changes, infection or scarring. They should not be treated as interchangeable menu items or attempted with professional-strength products at home.'),
('Discuss pigmentation carefully','Darker marks may have more than one cause. Sun exposure and irritation can complicate progress. Ask about sun protection and whether your current products are contributing to irritation. Persistent or changing pigmentation deserves assessment rather than a promise that one facial will remove it.'),
('Define improvement realistically','Scars may become less noticeable without disappearing. Ask how progress will be assessed and when the plan should be reviewed. Photographs can help only with proper consent and consistent conditions. Do not use another person’s result as a forecast of your own response.')],['microneedling','chemical-peels','acne-scar-consultation','pigmentation-consultation'], [('American Academy of Dermatology: acne scars','https://www.aad.org/public/diseases/acne/derm-treat/scars/treatment/')]),
('laser-hair-removal','Laser Hair Removal: Sessions, Preparation and Safety','TREATMENT GUIDE','portrait','A considered plan accounts for your skin, hair and the technology being used.',[
('Hair reduction, with realistic limits','Laser hair removal targets pigment in hair follicles. The goal is reduction in unwanted hair growth. Response depends on factors including hair colour, skin tone, treatment area and the device. Maintenance may be needed, and permanent complete removal should not be promised.'),
('Why session counts vary','Hair grows in cycles, so one appointment does not address every follicle in the same way. A plan needs to account for your response and the area being treated. Ask how the practitioner decides the interval between sessions and when they would reassess an ineffective course, rather than relying on a universal package size.'),
('Choose experience with your skin tone','Ask which device will be used and about the practitioner’s experience treating skin similar to yours. Settings and technique matter. Discuss patch testing and eye protection. The possibility of burns, pigment changes and other adverse effects should be explained before consent.'),
('Prepare with personalised instructions','Tell the practitioner about tanning, medicines, supplements, infections and previous reactions. Ask when to shave and which hair removal methods or products to avoid beforehand. Follow the instructions for your particular plan rather than copying a generic internet schedule.'),
('Consider sun exposure in your routine','If you spend time outdoors in Mirpur or are travelling, discuss how that affects timing and aftercare. Ask about sun protection and when normal skincare can resume. Report unexpected pain, blistering or concerning skin changes promptly using the clinic’s agreed contact arrangements.'),
('Know when to pause','A treatment should be reviewed if your skin reacts unexpectedly or the expected progress is not happening. Ask what happens if a session needs postponing and how costs are handled. A good plan allows adjustment rather than requiring every session to proceed regardless of your skin.')],['laser-hair-removal'], [('Mayo Clinic: laser hair removal','https://www.mayoclinic.org/tests-procedures/laser-hair-removal/about/pac-20394555')]),
('prp-for-hair','PRP for Hair: How It Works and Who May Benefit','HAIR & SCALP','hair','A diagnosis comes before a procedure when you are concerned about thinning or shedding.',[
('First, understand the hair loss','Hair shedding and thinning have many possible causes. Pattern hair loss, illness, medicines and other conditions may need different management. Tell your practitioner when the change started, whether it is patchy or diffuse and whether you have scalp symptoms. Sudden or unexplained loss deserves assessment.'),
('What PRP involves','Platelet-rich plasma is prepared from a sample of your own blood. The sample is processed and a platelet-containing portion is injected into the scalp. The use of your own blood does not make the procedure risk-free: pain, bleeding, bruising and infection are among the issues to discuss.'),
('Who might consider it','PRP may be considered for selected people with pattern hair loss. Suitability depends on diagnosis, medical history and the condition of the scalp. It is not an answer to every cause of shedding, and it should not delay investigation of an underlying problem.'),
('Be clear about the evidence','Studies suggest possible benefit for some patients, but preparation methods, treatment schedules and outcome measures vary. This makes a precise personal forecast difficult. Ask how PRP compares with other appropriate options and what uncertainty remains in your case.'),
('Ask about the whole plan','Discuss the number and timing of proposed visits, total costs, aftercare and how progress will be assessed. Ask whether other treatment is recommended alongside PRP. Standardised photographs may be useful with consent, but changes in lighting or hair styling can make comparisons misleading.'),
('PRP and transplant consultations are different','A hair transplant consultation assesses a surgical option, including donor hair and long-term planning. PRP does not substitute for that assessment. If researching restoration in Mirpur, begin with a diagnosis and a conversation about realistic options rather than choosing a procedure from social media.')],['hair-prp','hair-restoration-consultation','hair-transplant-consultation'], [('Cleveland Clinic: PRP therapy','https://my.clevelandclinic.org/cosmetic-plastic-surgery/procedures/prp-therapy')])]
data=[dict(slug=s,title=t,category=c,image=i,lead=l,sections=[dict(heading=h,text=x) for h,x in sec],services=sv,references=[dict(title=a,url=b) for a,b in refs],status='draft',metaDescription=l+' Read consultation questions and practical considerations for Mirpur, AJK.') for s,t,c,i,l,sec,sv,refs in articles]
put('lib/articles.json',json.dumps(data,ensure_ascii=False,indent=2))
put('components/JournalCards.tsx', '''import Link from 'next/link';import Photo from './Photo';import articles from '@/lib/articles.json';import {preview} from '@/lib/config';export function JournalCards({all=false}:{all?:boolean}){return <div className="journal-grid">{articles.slice(0,all?5:3).map(a=><article key={a.slug}><Link href={preview?`/preview/journal/${a.slug}`:'/journal'} aria-label={preview?`Preview draft: ${a.title}`:`Journal: ${a.title}`}><Photo name={a.image}/><div className="article-meta"><span>{a.category}</span><span>AWAITING CLINICAL REVIEW</span></div><h3>{a.title} <span>↗</span></h3><p>{preview?a.lead:'Article in preparation. Available after clinical review.'}</p></Link></article>)}</div>}
''')
put('app/journal/page.tsx', '''import {JournalCards} from '@/components/JournalCards';import {meta} from '@/lib/seo';export const metadata=meta('The Revive Journal','Considered reading on skin, aesthetics and hair. Our educational articles are in preparation and await clinical review before publication.','/journal');export default function Page(){return <div className="section page"><span className="eyebrow">THE REVIVE JOURNAL</span><h1>Informed choices.<br/><em>A fresh perspective.</em></h1><p className="lede">Thoughtful reading, in preparation. Our health articles will be published after review by a qualified clinician.</p><JournalCards all/></div>}
''')
put('components/Article.tsx', '''import Link from 'next/link';import articles from '@/lib/articles.json';import {services} from '@/lib/services';import Photo from './Photo';export default function Article({article:a}:{article:typeof articles[number]}){return <article className="article-page section page"><aside className="draft-notice">UNPUBLISHED DRAFT · For qualified clinician review. Not approved for patient guidance.</aside><nav aria-label="Breadcrumb"><Link href="/">Home</Link> / <Link href="/journal">Journal</Link> / Draft preview</nav><span className="eyebrow">{a.category}</span><h1>{a.title}</h1><p className="lede">{a.lead}</p><Photo name={a.image}/><div className="article-body">{a.sections.map(s=><section key={s.heading}><h2>{s.heading}</h2><p>{s.text}</p></section>)}<section><h2>Continue your conversation</h2><p>Explore these consultation options at Revive in Mirpur. Individual suitability must be assessed before treatment.</p>{a.services.map(slug=><Link className="article-service" key={slug} href={`/treatments/${slug}`}>{services.find(s=>s.slug===slug)?.name} ↗</Link>)}<p><Link href="/contact">Contact the clinic</Link> to discuss a consultation. <Link href="/specialists">Practitioner profiles</Link> will be available when verified.</p></section><section><h2>Further reading & review notes</h2><p>This original editorial draft has not been medically reviewed. References offer background information, not evidence of clinical approval of this article.</p>{a.references.map(ref=><p key={ref.url}><a href={ref.url} target="_blank" rel="noreferrer">{ref.title} ↗</a></p>)}</section><section><h2>Related reading</h2>{articles.filter(b=>b.slug!==a.slug).slice(0,2).map(b=><Link className="article-service" key={b.slug} href={`/preview/journal/${b.slug}`}>{b.title} ↗</Link>)}</section></div></article>}
''')
put('app/preview/journal/[slug]/page.tsx', '''import {notFound} from 'next/navigation';import articles from '@/lib/articles.json';import Article from '@/components/Article';import {preview} from '@/lib/config';import {meta} from '@/lib/seo';export async function generateMetadata({params}:{params:Promise<{slug:string}>}){const {slug}=await params;const a=articles.find(a=>a.slug===slug);return a?meta(a.title,a.metaDescription,`/preview/journal/${slug}`,true):{}}export default async function Page({params}:{params:Promise<{slug:string}>}){if(!preview)notFound();const {slug}=await params;const a=articles.find(a=>a.slug===slug);if(!a)notFound();return <Article article={a}/>}
''')
put('app/journal/[slug]/page.tsx', '''import {notFound} from 'next/navigation';export default function Page(){notFound()}
''')
